WITH RECURSIVE chain(sample_id,depth,name,parent_id) AS (SELECT s.id,c.depth,f.name,c.parent_id FROM cpu_profile_stack_sample s JOIN stack_profile_callsite c ON c.id=s.callsite_id JOIN stack_profile_frame f ON f.id=c.frame_id UNION ALL SELECT chain.sample_id,c.depth,f.name,c.parent_id FROM chain JOIN stack_profile_callsite c ON c.id=chain.parent_id JOIN stack_profile_frame f ON f.id=c.frame_id), paths AS (SELECT sample_id,group_concat(name,';') AS stack FROM (SELECT sample_id,name FROM chain ORDER BY sample_id,depth) GROUP BY sample_id) SELECT stack,COUNT(*) AS samples FROM paths GROUP BY stack ORDER BY samples DESC;
